def combi(n, k):
	res = 1
	for i in range(k):
		res *= n - i
	for i in range(k):
		res //= i + 1
	return res
T = int(input())
for case in range(T):
	(n, k, m) = map(int, input().split())
	if combi(n, k) < m:
		print(-1)
		continue
	b = []
	for i in range(n):
		rem_bits = n - i
		if rem_bits == k or combi(rem_bits - 1, k) < m:
			b.append('1')
			m -= combi(rem_bits - 1, k)
			k -= 1
		else:
			b.append('0')
	print(''.join(b))
